//! Hemi system transaction types.
//!
//! Hemi adds two protocol-only transaction types to the OP Stack, mirroring hemilabs/op-geth:
//!
//! - `0x7C` [`TxBtcAttributesDeposited`]: generated by the sequencer's execution client, it carries
//!   the Bitcoin headers that advance the hVM consensus view of Bitcoin
//!   (`HvmState.update(...)`).
//! - `0x7D` [`TxPopPayout`]: generated by op-node, it mints the Proof-of-Proof rewards
//!   (`GovernanceToken.mintPoPRewards(...)`).
//!
//! Both are unsigned, are sent by [`HEMI_SYSTEM_SENDER`], pay no fees and are executed like
//! deposits. Their body is the RLP list `[to, gas, data]` where `to` is an optional address
//! (encoded as the empty string when absent), and their hash is
//! `keccak256(type || rlp([to, gas, data]))`.

use alloc::vec::Vec;
use alloy_consensus::{Sealable, Transaction, Typed2718, transaction::RlpEcdsaEncodableTx};
use alloy_eips::{
    eip2718::{Decodable2718, Eip2718Error, Eip2718Result, Encodable2718, IsTyped2718},
    eip2930::AccessList,
};
use alloy_primitives::{Address, B256, Bytes, ChainId, TxHash, TxKind, U256, address, keccak256};
use alloy_rlp::{BufMut, Decodable, Encodable, Header};

/// Type byte of the Hemi Bitcoin Attributes Deposited transaction.
pub const BTC_ATTRIBUTES_DEPOSITED_TX_TYPE_ID: u8 = 0x7C;

/// Type byte of the Hemi PoP payout transaction.
pub const POP_PAYOUT_TX_TYPE_ID: u8 = 0x7D;

/// The sender of all Hemi system transactions (PoP payout and Bitcoin Attributes Deposited).
pub const HEMI_SYSTEM_SENDER: Address = address!("0x8888888888888888888888888888888888888888");

/// Returns `true` if `ty` is one of the Hemi system transaction types.
pub const fn is_hemi_system_tx_type(ty: u8) -> bool {
    ty == BTC_ATTRIBUTES_DEPOSITED_TX_TYPE_ID || ty == POP_PAYOUT_TX_TYPE_ID
}

/// Encodes an optional address the way go-ethereum encodes a `*common.Address` tagged `rlp:"nil"`.
fn encode_opt_address(to: &Option<Address>, out: &mut dyn BufMut) {
    match to {
        Some(to) => to.encode(out),
        None => out.put_u8(alloy_rlp::EMPTY_STRING_CODE),
    }
}

const fn opt_address_length(to: &Option<Address>) -> usize {
    match to {
        Some(_) => 21,
        None => 1,
    }
}

fn decode_opt_address(buf: &mut &[u8]) -> alloy_rlp::Result<Option<Address>> {
    if buf.first() == Some(&alloy_rlp::EMPTY_STRING_CODE) {
        *buf = &buf[1..];
        return Ok(None);
    }
    Ok(Some(Address::decode(buf)?))
}

macro_rules! hemi_system_tx {
    ($(#[$meta:meta])* $name:ident, $ty:expr, $label:literal) => {
        $(#[$meta])*
        #[derive(Debug, Clone, PartialEq, Eq, Hash, Default)]
        #[cfg_attr(feature = "arbitrary", derive(arbitrary::Arbitrary))]
        #[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
        #[cfg_attr(feature = "serde", serde(rename_all = "camelCase"))]
        pub struct $name {
            /// The contract called by the transaction.
            pub to: Option<Address>,
            /// Gas limit.
            #[cfg_attr(feature = "serde", serde(with = "alloy_serde::quantity", rename = "gas"))]
            pub gas_limit: u64,
            /// ABI-encoded contract call.
            pub input: Bytes,
        }

        impl $name {
            /// The EIP-2718 type byte.
            pub const TYPE: u8 = $ty;

            /// Returns the (empty) signature used for this unsigned transaction type.
            pub const fn signature() -> alloy_primitives::Signature {
                alloy_primitives::Signature::new(U256::ZERO, U256::ZERO, false)
            }

            /// Returns the sender of the transaction, [`HEMI_SYSTEM_SENDER`].
            pub const fn signer_address(&self) -> Address {
                HEMI_SYSTEM_SENDER
            }

            fn rlp_payload_length(&self) -> usize {
                opt_address_length(&self.to) + self.gas_limit.length() + self.input.length()
            }

            fn rlp_header(&self) -> Header {
                Header { list: true, payload_length: self.rlp_payload_length() }
            }

            /// Length of the RLP list `[to, gas, data]`.
            pub fn rlp_encoded_length(&self) -> usize {
                self.rlp_header().length_with_payload()
            }

            /// Encodes the RLP list `[to, gas, data]`.
            pub fn rlp_encode(&self, out: &mut dyn BufMut) {
                self.rlp_header().encode(out);
                self.rlp_encode_fields_inner(out);
            }

            fn rlp_encode_fields_inner(&self, out: &mut dyn BufMut) {
                encode_opt_address(&self.to, out);
                self.gas_limit.encode(out);
                self.input.encode(out);
            }

            /// Decodes the RLP list `[to, gas, data]`.
            pub fn rlp_decode(buf: &mut &[u8]) -> alloy_rlp::Result<Self> {
                let header = Header::decode(buf)?;
                if !header.list {
                    return Err(alloy_rlp::Error::UnexpectedString);
                }
                let remaining = buf.len();
                if header.payload_length > remaining {
                    return Err(alloy_rlp::Error::InputTooShort);
                }
                let to = decode_opt_address(buf)?;
                let gas_limit = Decodable::decode(buf)?;
                let input = Decodable::decode(buf)?;
                if buf.len() + header.payload_length != remaining {
                    return Err(alloy_rlp::Error::ListLengthMismatch {
                        expected: header.payload_length,
                        got: remaining - buf.len(),
                    });
                }
                Ok(Self { to, gas_limit, input })
            }

            /// Length including the type byte.
            pub fn eip2718_encoded_length(&self) -> usize {
                self.rlp_encoded_length() + 1
            }

            fn network_header(&self) -> Header {
                Header { list: false, payload_length: self.eip2718_encoded_length() }
            }

            /// Length including the outer network RLP header.
            pub fn network_encoded_length(&self) -> usize {
                self.network_header().length_with_payload()
            }

            /// Network encodes the transaction.
            pub fn network_encode(&self, out: &mut dyn BufMut) {
                self.network_header().encode(out);
                self.encode_2718(out);
            }

            /// Heuristic for the in-memory size of the transaction.
            pub fn size(&self) -> usize {
                core::mem::size_of::<Self>() + self.input.len()
            }

            /// Calculates the transaction hash.
            pub fn tx_hash(&self) -> TxHash {
                let mut buf = Vec::with_capacity(self.eip2718_encoded_length());
                self.encode_2718(&mut buf);
                keccak256(&buf)
            }
        }

        impl Typed2718 for $name {
            fn ty(&self) -> u8 {
                $ty
            }
        }

        impl IsTyped2718 for $name {
            fn is_type(ty: u8) -> bool {
                ty == $ty
            }
        }

        impl RlpEcdsaEncodableTx for $name {
            fn rlp_encoded_fields_length(&self) -> usize {
                self.rlp_payload_length()
            }

            fn rlp_encode_fields(&self, out: &mut dyn alloy_rlp::BufMut) {
                self.rlp_encode_fields_inner(out);
            }
        }

        impl Transaction for $name {
            fn chain_id(&self) -> Option<ChainId> {
                None
            }
            fn nonce(&self) -> u64 {
                0
            }
            fn gas_limit(&self) -> u64 {
                self.gas_limit
            }
            fn gas_price(&self) -> Option<u128> {
                None
            }
            fn max_fee_per_gas(&self) -> u128 {
                0
            }
            fn max_priority_fee_per_gas(&self) -> Option<u128> {
                None
            }
            fn max_fee_per_blob_gas(&self) -> Option<u128> {
                None
            }
            fn priority_fee_or_price(&self) -> u128 {
                0
            }
            fn effective_gas_price(&self, _: Option<u64>) -> u128 {
                0
            }
            fn is_dynamic_fee(&self) -> bool {
                false
            }
            fn kind(&self) -> TxKind {
                self.to.map_or(TxKind::Create, TxKind::Call)
            }
            fn is_create(&self) -> bool {
                self.to.is_none()
            }
            fn value(&self) -> U256 {
                U256::ZERO
            }
            fn input(&self) -> &Bytes {
                &self.input
            }
            fn access_list(&self) -> Option<&AccessList> {
                None
            }
            fn blob_versioned_hashes(&self) -> Option<&[B256]> {
                None
            }
            fn authorization_list(&self) -> Option<&[alloy_eips::eip7702::SignedAuthorization]> {
                None
            }
        }

        impl Encodable2718 for $name {
            fn type_flag(&self) -> Option<u8> {
                Some($ty)
            }
            fn encode_2718_len(&self) -> usize {
                self.eip2718_encoded_length()
            }
            fn encode_2718(&self, out: &mut dyn alloy_rlp::BufMut) {
                out.put_u8($ty);
                self.rlp_encode(out);
            }
        }

        impl Decodable2718 for $name {
            fn typed_decode(ty: u8, data: &mut &[u8]) -> Eip2718Result<Self> {
                if ty != $ty {
                    return Err(Eip2718Error::UnexpectedType(ty));
                }
                Ok(Self::rlp_decode(data)?)
            }

            fn fallback_decode(_data: &mut &[u8]) -> Eip2718Result<Self> {
                Err(Eip2718Error::UnexpectedType($ty))
            }
        }

        impl Encodable for $name {
            fn encode(&self, out: &mut dyn BufMut) {
                self.rlp_encode(out);
            }

            fn length(&self) -> usize {
                self.rlp_encoded_length()
            }
        }

        impl Decodable for $name {
            fn decode(data: &mut &[u8]) -> alloy_rlp::Result<Self> {
                Self::rlp_decode(data)
            }
        }

        impl Sealable for $name {
            fn hash_slow(&self) -> B256 {
                self.tx_hash()
            }
        }

        #[cfg(feature = "alloy-compat")]
        impl From<$name> for alloy_rpc_types_eth::TransactionRequest {
            fn from(tx: $name) -> Self {
                Self {
                    from: Some(HEMI_SYSTEM_SENDER),
                    to: Some(tx.kind()),
                    transaction_type: Some($ty),
                    gas: Some(tx.gas_limit),
                    gas_price: Some(0),
                    value: Some(U256::ZERO),
                    input: tx.input.into(),
                    ..Default::default()
                }
            }
        }
    };
}

hemi_system_tx!(
    /// Hemi PoP payout transaction (type `0x7D`), calling `GovernanceToken.mintPoPRewards`.
    TxPopPayout,
    POP_PAYOUT_TX_TYPE_ID,
    "pop payout"
);

hemi_system_tx!(
    /// Hemi Bitcoin Attributes Deposited transaction (type `0x7C`), calling `HvmState.update`.
    TxBtcAttributesDeposited,
    BTC_ATTRIBUTES_DEPOSITED_TX_TYPE_ID,
    "bitcoin attributes deposited"
);

/// Serializes a sealed Hemi system transaction the way hemilabs/op-geth renders it over RPC.
///
/// go-ethereum's `UnmarshalJSON` (used by op-node and other Go clients) requires `to`, `gas`,
/// `gasPrice` and `input` to be present for these types; `gasPrice` (always zero), `from` and the
/// effective `nonce` are added by the RPC transaction wrapper.
#[cfg(feature = "serde")]
pub fn serde_hemi_system_tx_rpc<T, S>(
    value: &alloy_consensus::Sealed<T>,
    serializer: S,
) -> Result<S::Ok, S::Error>
where
    T: Transaction + Typed2718,
    S: serde::Serializer,
{
    use serde::Serialize;

    #[derive(Serialize)]
    #[serde(rename_all = "camelCase")]
    struct SerdeHelper<'a> {
        hash: B256,
        #[serde(rename = "type", with = "alloy_serde::quantity")]
        tx_type: u8,
        to: Option<Address>,
        #[serde(with = "alloy_serde::quantity")]
        gas: u64,
        value: U256,
        input: &'a Bytes,
    }

    let tx = value.inner();
    SerdeHelper {
        hash: value.hash(),
        tx_type: tx.ty(),
        to: tx.to(),
        gas: tx.gas_limit(),
        value: U256::ZERO,
        input: tx.input(),
    }
    .serialize(serializer)
}

/// Deserializes a sealed Hemi system transaction from its RPC representation.
#[cfg(feature = "serde")]
pub fn serde_hemi_system_tx_rpc_de<'de, T, D>(
    deserializer: D,
) -> Result<alloy_consensus::Sealed<T>, D::Error>
where
    T: From<(Option<Address>, u64, Bytes)>,
    D: serde::Deserializer<'de>,
{
    use serde::Deserialize;

    #[derive(Deserialize)]
    struct SerdeHelper {
        hash: B256,
        #[serde(default)]
        to: Option<Address>,
        #[serde(with = "alloy_serde::quantity")]
        gas: u64,
        input: Bytes,
    }

    let SerdeHelper { hash, to, gas, input } = SerdeHelper::deserialize(deserializer)?;
    Ok(alloy_consensus::Sealed::new_unchecked(T::from((to, gas, input)), hash))
}

impl From<(Option<Address>, u64, Bytes)> for TxPopPayout {
    fn from((to, gas_limit, input): (Option<Address>, u64, Bytes)) -> Self {
        Self { to, gas_limit, input }
    }
}

impl From<(Option<Address>, u64, Bytes)> for TxBtcAttributesDeposited {
    fn from((to, gas_limit, input): (Option<Address>, u64, Bytes)) -> Self {
        Self { to, gas_limit, input }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloy_primitives::hex;

    #[test]
    fn roundtrip_and_hash_matches_go_ethereum_rlp() {
        let tx = TxBtcAttributesDeposited {
            to: Some(address!("0x4200000000000000000000000000000000000042")),
            gas_limit: 1_000_000,
            input: Bytes::from_static(&hex!("deadbeef")),
        };
        let mut buf = Vec::new();
        tx.encode_2718(&mut buf);
        assert_eq!(buf[0], 0x7C);
        // [to(21), gas(4), data(5)] => list header 0xde
        assert_eq!(buf[1], 0xc0 + 30);
        let decoded = TxBtcAttributesDeposited::decode_2718(&mut buf.as_slice()).unwrap();
        assert_eq!(decoded, tx);
        assert_eq!(tx.tx_hash(), keccak256(&buf));

        let none = TxPopPayout { to: None, gas_limit: 0, input: Bytes::new() };
        let mut buf = Vec::new();
        none.encode_2718(&mut buf);
        assert_eq!(buf, hex!("7dc3808080"));
        assert_eq!(TxPopPayout::decode_2718(&mut buf.as_slice()).unwrap(), none);
    }
}
